<?php namespace App\Services; class WhatsappService { public function link(array $loja,array $cliente,float $saldo,string $message=''): string { $number=preg_replace('/\D/','',$cliente['telefone']??''); if(strlen($number)<=11) $number='55'.$number; $text=$message ?: "Olá, {$cliente['nome']}. Aqui é da {$loja['nome_loja']}. Consta um saldo em aberto de R$ ".number_format($saldo,2,',','.')." no seu fiado.".(empty($loja['chave_pix'])?'':" Se puder, regularize pelo Pix: {$loja['chave_pix']}.").' Obrigado.'; return 'https://wa.me/'.$number.'?text='.rawurlencode($text); } }
